pragma solidity ^0.8.20;
contract EventRegistry {
    address public immutable owner;
    struct Chapter { uint256 id; string title; }
    Chapter[] public chapters;
    event ChapterAdded(uint256 indexed chapterId, string title, address indexed actor);
    constructor() { owner = msg.sender; }
    function addChapter(string calldata title) external {
        require(msg.sender == owner, "not owner");
        uint256 id = chapters.length;
        chapters.push(Chapter(id, title));
        emit ChapterAdded(id, title, msg.sender);
    }
}

